-- PT106-S1-Q12. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT106-S1-Q12$batch04$ AND q.stimulus=$batch04$People who say that Dooney County is flat are clearly wrong. On flat land, soil erosion by water is not a problem. Consequently, farmers whose land is flat do not build terraces to prevent erosion. Yet I hear that the farms in Dooney County are dotted with terraces.$batch04$ AND q.prompt=$batch04$The author's conclusion in the passage depends on the assumption that$batch04$ AND q.correct_choice=$batch04$B$batch04$) THEN RAISE EXCEPTION 'Question changed: PT106-S1-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT106-S1-Q12$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT106-S1-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT106-S1-Q12$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$People who say Dooney County is flat are wrong.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$On flat land, water erosion is not a problem, so farmers on flat land do not build terraces to prevent erosion. Dooney County's farms are dotted with terraces.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The premise only rules out terraces built *to prevent erosion* on flat land. Farmers might build terraces for some other reason. If Dooney's terraces were built for something else, they tell us nothing about whether the land is flat.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A link: the terraces in Dooney County were built to prevent erosion.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT106-S1-Q12$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$The argument does not need water to be the *only* cause of erosion.$batch04$), ($batch04$B$batch04$, $batch04$Negate it: *none* of the terraces in Dooney County were built to prevent erosion. Then the evidence about flat land and erosion terraces does not apply, and the terraces say nothing about the land.$batch04$), ($batch04$C$batch04$, $batch04$What matters is why the farmers built the terraces, not whether the terraces actually work.$batch04$), ($batch04$D$batch04$, $batch04$The stimulus says erosion is not a *problem* on flat land. The argument does not need there to be no erosion at all.$batch04$), ($batch04$E$batch04$, $batch04$Terraces elsewhere in the county do not affect the argument, which rests on the terraces on farms.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT106-S1-Q12$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
